def rate(self, from_currency: str, to_currency: str) -> float:
    for currency in (from_currency, to_currency):
        if currency not in self.rates_to_cny:
            raise ValueError(f"汇率表不支持币种：{currency}")
    return self.rates_to_cny[to_currency] / self.rates_to_cny[from_currency]

@staticmethod
def from_major_units(major: float, currency: str) -> "Money":
    # 简化处理：所有支持币种均按 100 倍换算（JPY 实际为 1，demo 暂统一）
    return Money.of(int(major * 100), currency)

@dataclass(frozen=True)
class ExchangeRateTable:
    rates_to_cny: dict[str, float] = field(default_factory=lambda: dict(_RATES_TO_CNY))

